function filterFieldsByType<T extends object>(source: any, requiredFields: (keyof T)[]): Partial<T> {
    const result: Partial<T> = {};
    for (const key of requiredFields) {
        if (key in source) {
            if (source[key] !== '')
                result[key] = source[key];
        }
    }
    return result;
}
