        const pisProperties = filterFieldsByType(pis, required);
        const pisObject: PIS = { [pisKey]: pisProperties } as PIS;
        return pisObject;
    }
    console.warn(`Chave PIS '${pisKey}' não reconhecida.`);
    return {} as PIS;
}
export const mountICMS = (icms: dadosICMS): ICMS => {
