        cod_sit = CST.length > 2 ? CST.substring(1, 3) : CST;
    } else if (CSOSN) {
        tipo_sit_trib = 'CSOSN';
        CSOSN?.trim()?.length > 3 ? cod_sit = CSOSN.substring(1, 4) : cod_sit = String(CSOSN);
