					</xs:simpleType>
				</xs:element>
				<xs:element name="cOrgaoAutor" type="TCOrgaoIBGE"/>
				<xs:element name="tpAutor">
					<xs:simpleType>
						<xs:annotation>
							<xs:documentation>1=Empresa Emitente; 2=Empresa Destinatária; 3=Empresa; 5=Fisco; 6=RFB; 9=Outros;</xs:documentation>
						</xs:annotation>
						<xs:restriction base="xs:string">
							<xs:whiteSpace value="preserve"/>
							<xs:enumeration value="1"/>
						</xs:restriction>
					</xs:simpleType>
				</xs:element>
				<xs:element name="verAplic" type="TVerAplic">
					<xs:annotation>
						<xs:documentation>Versão do Aplicativo do Autor do Evento</xs:documentation>
					</xs:annotation>
				</xs:element>
				<xs:element name="nProtEvento" type="TProt">
					<xs:annotation>
						<xs:documentation>Número do Protocolo de Autorização do Evento da NF-e a que se refere este cancelamento.</xs:documentation>
					</xs:annotation>
				</xs:element>
			</xs:sequence>
			<xs:attribute name="versao" use="required">
				<xs:simpleType>
					<xs:restriction base="xs:string">
						<xs:whiteSpace value="preserve"/>
						<xs:enumeration value="1.00"/>
					</xs:restriction>
				</xs:simpleType>
			</xs:attribute>
		</xs:complexType>
	</xs:element>
</xs:schema><?xml version="1.0" encoding="UTF-8"?>
<xs:schema xmlns:xs="http://www.w3.org/2001/XMLSchema" xmlns="http://www.portalfiscal.inf.br/nfe" xmlns:ds="http://www.w3.org/2000/09/xmldsig#" targetNamespace="http://www.portalfiscal.inf.br/nfe" elementFormDefault="qualified" attributeFormDefault="unqualified">
	<xs:include schemaLocation="tiposBasico_v1.03.xsd"/>
	<xs:element name="detEvento">
		<xs:complexType>
			<xs:sequence>
				<xs:element ref="descEvento"/>
				<xs:element ref="cOrgaoAutor"/>
				<xs:element ref="tpAutor"/>
				<xs:element ref="verAplic"/>
				<xs:element ref="dhEmi"/>
				<xs:element ref="tpNF"/>
				<xs:element ref="IE"/>
				<xs:element name="dest">
					<xs:complexType>
						<xs:sequence>
							<xs:element ref="UF"/>
							<xs:choice>
								<xs:element name="CNPJ" type="TCnpj"/>
								<xs:element name="CPF" type="TCpf"/>
								<xs:element name="idEstrangeiro">
									<xs:annotation>
										<xs:documentation>Identificador do destinatário, em caso de comprador estrangeiro</xs:documentation>
									</xs:annotation>
									<xs:simpleType>
										<xs:restriction base="xs:string">
											<xs:whiteSpace value="preserve"/>
											<xs:pattern value="([!-ÿ]{0}|[!-ÿ]{5,20})?"/>
										</xs:restriction>
									</xs:simpleType>
								</xs:element>
							</xs:choice>
							<xs:element ref="IE" minOccurs="0"/>
							<xs:element ref="vNF"/>
							<xs:element ref="vICMS"/>
							<xs:element ref="vST"/>
						</xs:sequence>
					</xs:complexType>
				</xs:element>
			</xs:sequence>
			<xs:attribute name="versao" use="required">
				<xs:simpleType>
					<xs:restriction base="xs:string">
						<xs:whiteSpace value="preserve"/>
						<xs:enumeration value="1.00"/>
					</xs:restriction>
				</xs:simpleType>
			</xs:attribute>
		</xs:complexType>
	</xs:element>
	<xs:element name="descEvento">
		<xs:simpleType>
			<xs:restriction base="xs:string">
				<xs:whiteSpace value="preserve"/>
				<xs:enumeration value="EPEC"/>
			</xs:restriction>
		</xs:simpleType>
	</xs:element>
	<xs:element name="tpAutor">
		<xs:annotation>
			<xs:documentation>Neste evento, aceitar apenas 1. 1=Empresa Emitente; 2=Empresa Destinatária; 3=Empresa; 5=Fisco; 6=RFB; 9=Outros Órgãos</xs:documentation>
		</xs:annotation>
		<xs:simpleType>
			<xs:restriction base="xs:string">
				<xs:whiteSpace value="preserve"/>
				<xs:enumeration value="1"/>
			</xs:restriction>
		</xs:simpleType>
	</xs:element>
	<xs:element name="verAplic" type="TVerAplic">
		<xs:annotation>
			<xs:documentation>Versão do Aplicativo do Autor do Evento</xs:documentation>
		</xs:annotation>
	</xs:element>
	<xs:element name="dhEmi" type="TDateTimeUTC">
		<xs:annotation>
			<xs:documentation>Data de emissão no formato UTC.  AAAA-MM-DDThh:mm:ssTZD</xs:documentation>
		</xs:annotation>
	</xs:element>
	<xs:element name="tpNF">
		<xs:annotation>
			<xs:documentation>Tipo do Documento Fiscal (0 - entrada; 1 - saída)</xs:documentation>
		</xs:annotation>
		<xs:simpleType>
			<xs:restriction base="xs:string">
				<xs:whiteSpace value="preserve"/>
				<xs:enumeration value="0"/>
				<xs:enumeration value="1"/>
			</xs:restriction>
		</xs:simpleType>
	</xs:element>
	<xs:element name="cOrgaoAutor" type="TCodUfIBGE"/>
	<xs:element name="IE">
		<xs:annotation>
			<xs:documentation>Informar a IE. Para IE do destinatário somente quando o contribuinte possuir uma inscrição estadual</xs:documentation>
		</xs:annotation>
		<xs:simpleType>
			<xs:restriction base="xs:string">
				<xs:whiteSpace value="preserve"/>
				<xs:pattern value="[0-9]{2,14}"/>
			</xs:restriction>
		</xs:simpleType>
	</xs:element>
	<xs:element name="UF" type="TUf">
		<xs:annotation>
			<xs:documentation>Sigla UF do destinatário. Informar "EX" no caso de operação com o exterior</xs:documentation>
		</xs:annotation>
	</xs:element>
	<xs:element name="vNF" type="TDec_1302">
		<xs:annotation>
			<xs:documentation>Valor total da NF-e</xs:documentation>
		</xs:annotation>
	</xs:element>
	<xs:element name="vICMS" type="TDec_1302">
		<xs:annotation>
			<xs:documentation>Valor total do ICMS</xs:documentation>
		</xs:annotation>
	</xs:element>
	<xs:element name="vST" type="TDec_1302">
		<xs:annotation>
			<xs:documentation>Valor total do ICMS de Substituição Tributária</xs:documentation>
		</xs:annotation>
	</xs:element>
</xs:schema><?xml version="1.0" encoding="UTF-8"?>
<xs:schema xmlns:xs="http://www.w3.org/2001/XMLSchema" xmlns="http://www.portalfiscal.inf.br/nfe" xmlns:ds="http://www.w3.org/2000/09/xmldsig#" targetNamespace="http://www.portalfiscal.inf.br/nfe" elementFormDefault="qualified" attributeFormDefault="unqualified">
  <xs:include schemaLocation="tiposBasico_v1.03.xsd"/>
  <xs:element name="detEvento">
    <xs:annotation>
      <xs:documentation>Informações do Pedido de Prorrogação</xs:documentation>
    </xs:annotation>
    <xs:complexType>
      <xs:sequence>
        <xs:element name="descEvento">
          <xs:annotation>
            <xs:documentation>Pedido de Prorrogação ou Pedido de Prorrogacao</xs:documentation>
          </xs:annotation>
          <xs:simpleType>
            <xs:restriction base="xs:string">
              <xs:enumeration value="Pedido de Prorrogação" />
              <xs:enumeration value="Pedido de Prorrogacao" />
            </xs:restriction>
          </xs:simpleType>
        </xs:element>
        <xs:element name="nProt" type="TProt" >
          <xs:annotation>
            <xs:documentation>Informar o número do Protocolo de Autorização da NF-e a ser Prorrogada. (vide item 5.6).</xs:documentation>
          </xs:annotation>
        </xs:element>
        <xs:element maxOccurs="990" minOccurs="1" name="itemPedido">
          <xs:annotation>
            <xs:documentation>Item do Pedido de Prorrogação. Recomenda-se agrupar a maior quantidade de itens em cada Pedido de Prorrogação</xs:documentation>
          </xs:annotation>
          <xs:complexType>
            <xs:sequence>
              <xs:element name="qtdeItem" type="TDec_1104v">
                <xs:annotation>
                  <xs:documentation>Quantidade do item que será solicitado a prorrogação de prazo</xs:documentation>
                </xs:annotation>
              </xs:element>
            </xs:sequence>
            <xs:attribute name="numItem">
              <xs:annotation>
                <xs:documentation>Número do item da NF-e. O número do item deverá ser o mesmo número do item na NF-e</xs:documentation>
              </xs:annotation>
              <xs:simpleType>
                <xs:restriction base="xs:string">
                  <xs:whiteSpace value="preserve"/>
                  <xs:pattern value="[0-9]{1,3}"/>
                </xs:restriction>
              </xs:simpleType>
            </xs:attribute>
          </xs:complexType>
	    </xs:element>
      </xs:sequence>
      <xs:attribute name="versao" >
        <xs:annotation>
          <xs:documentation>Versão do Pedido de Prorrogação</xs:documentation>
        </xs:annotation>
        <xs:simpleType>
          <xs:restriction base="xs:string">
            <xs:whiteSpace value="preserve"/>
            <xs:enumeration value="1.00"/>
          </xs:restriction>
        </xs:simpleType>
      </xs:attribute>
    </xs:complexType>
	<xs:unique name="pk_numItem">
		<xs:selector xpath="./*"/>
		<xs:field xpath="@numItem"/>
	</xs:unique>
  </xs:element>
