																<xs:simpleType>
																	<xs:restriction base="xs:string">
																		<xs:whiteSpace value="preserve"/>
																		<xs:pattern value="[0-9]{1,5}"/>
																	</xs:restriction>
																</xs:simpleType>
															</xs:element>
