													</xs:complexType>
												</xs:element>
												<xs:element name="infProdEmb" minOccurs="0">
													<xs:annotation>
														<xs:documentation>Informações mais detalhadas do produto (usada na NFF)</xs:documentation>
													</xs:annotation>
