																		<xs:maxLength value="8"/>
																		<xs:minLength value="1"/>
																	</xs:restriction>
																</xs:simpleType>
															</xs:element>
															<xs:element name="qVolEmb" type="TDec_0803v">
																<xs:annotation>
																	<xs:documentation>Volume do produto na embalagem</xs:documentation>
																</xs:annotation>
