																		<xs:restriction base="xs:string">
																			<xs:length value="17"/>
																			<xs:whiteSpace value="preserve"/>
																			<xs:pattern value="[A-Z0-9]+"/>
																		</xs:restriction>
																	</xs:simpleType>
																</xs:element>
