																			<xs:maxLength value="4"/>
																		</xs:restriction>
																	</xs:simpleType>
																</xs:element>
																<xs:element name="xCor">
																	<xs:annotation>
																		<xs:documentation>Descrição da cor</xs:documentation>
																	</xs:annotation>
