																	<xs:annotation>
																		<xs:documentation>Peso bruto</xs:documentation>
																	</xs:annotation>
																	<xs:simpleType>
																		<xs:restriction base="TString">
																			<xs:minLength value="1"/>
																			<xs:maxLength value="9"/>
																		</xs:restriction>
																	</xs:simpleType>
																</xs:element>
																<xs:element name="nSerie">
																	<xs:annotation>
																		<xs:documentation>Serial (série)</xs:documentation>
																	</xs:annotation>
