																		<xs:restriction base="TString">
																			<xs:minLength value="1"/>
																			<xs:maxLength value="9"/>
																		</xs:restriction>
																	</xs:simpleType>
																</xs:element>
																<xs:element name="dist">
																	<xs:annotation>
																		<xs:documentation>Distância entre eixos</xs:documentation>
																	</xs:annotation>
